import{_ as r,l as o,o as e,c as n,v as l,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"液冷与热设计","description":"","frontmatter":{"title":"液冷与热设计","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/liquid-cooling-thermal.md","filePath":"llm/liquid-cooling-thermal.md","lastUpdated":1789023840000}'),h={name:"llm/liquid-cooling-thermal.md"};function A(c,a,m,C,_,D){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="液冷与热设计" tabindex="-1">液冷与热设计 <a class="header-anchor" href="#液冷与热设计" aria-label="Permalink to &quot;液冷与热设计&quot;">​</a></h1><div class="epigraph"><p>风冷的极限是机柜能带走的热；液冷换的是传热介质，不是把热力学取消。水侧一停，加速器域比风扇停得更彻底。</p><footer>—— 对照高密度 GPU 机柜的冷板 / CDU 公开形态；功率密度见上一课</footer></div><p><a href="/llm/rack-power-density">上一课</a> 把卡数上限写成电。本课写热：同样的千瓦必须离开芯片。缺口是液冷如何改变故障模式与维护，而不是科普「水比空气热容大」。超节点产品形态公开为液冷托盘；<a href="/llm/nvlink">NVLink</a> 域、供电域、冷却域往往重叠成<strong>同一个爆炸半径</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风冷在 15 kW 以上机柜开始吃力：风量、噪声、热通道温度、以及 GPU 因进风不均而降频。冷板液冷把热从封装接到二次水，机柜可以堆到公开超节点那种密度。代价是：泄漏、水质、冷凝、CDU（分配单元）成为单点；维护要从「热插拔风扇」变成「关水、排液、换冷板」。问题是把冷却当成与 NCCL 同级的可用性输入：一次 CDU 故障可以让整柜 GPU 过热关机，step 丢失，等价于一次超大规模集体超时。</p><p>冷热不均同样有害：同一域里一张卡降频，All-Reduce 等最慢 rank，整步变慢。热设计失败表现为通信墙一样的症状，根因在进水温度与流量，不在算法。</p><p><span class="marginnote">一次水 / 二次水、CDU、歧管、冷板是常见分层。本课不画未公开的管路直径与流量公式。规划用厂商允许的进水温度范围与机房能否提供该水为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把冷却域画进拓扑图：哪些 GPU 共享 CDU、哪些共享歧管。故障演练按域下电，而不是按单卡。监控进水温度、回水温度、流量、泄漏传感器，与 GPU 热点、时钟、Xid 对齐时间轴——热事件往往先于 CUDA 错误。</p><p>作业调度避免在冷却余量不足时打满 Tensor Core 训练；降功率模式是保护，应告警为设施事件。液冷不能当「无限密度」：机房排热（冷却塔、外水）仍是屋顶线。PUE 变好只说明风扇电少了，厂级排热仍在。</p>',10)),(e(),s(E,null,{default:t(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIE%5B%22GPU%20%E5%B0%81%E8%A3%85%22%5D%20--%3E%20PLATE%5B%22%E5%86%B7%E6%9D%BF%22%5D%0A%20%20PLATE%20--%3E%20CDU%5B%22CDU%20%2F%20%E4%BA%8C%E6%AC%A1%E6%B0%B4%22%5D%0A%20%20CDU%20--%3E%20FAC%5B%22%E6%9C%BA%E6%88%BF%E6%8E%92%E7%83%AD%22%5D%0A%20%20CDU%20--%3E%20FAIL%5B%22%E5%86%B7%E5%8D%B4%E5%9F%9F%E6%95%85%E9%9A%9C%22%5D%0A%20%20FAIL%20--%3E%20RACK%5B%22%E6%95%B4%E6%9F%9C%E9%99%8D%E9%A2%91%E6%88%96%E5%85%B3%E6%9C%BA%22%5D%0A%20%20RACK%20--%3E%20STEP%5B%22%E9%9B%86%E4%BD%93%E7%AD%89%E5%BE%85%E6%9C%80%E6%85%A2%E5%8D%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>风冷机柜与液冷机柜混部时，不要按同一套进风假设做容量。也不要把液冷 GPU 插进只有风冷的机架——这不是软件开关。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>芯片功耗变成热流，冷板靠接触与流量带走。流量不足或气泡导致局部热阻上升，热点降频。同步训练让整柜同时进入高功耗，水侧看到的是方波；CDU 控制环若按缓慢的数据中心负荷设计，会在方波前沿过冲。这与网络拥塞控制环慢于集体脉冲是同一类「控制环跟不上训练时钟」的问题。</p><p>泄漏检测必须比电气保护更快：水进电是安全事件。因此液冷域的维护窗口更长，调度要预留，不能按风冷的热插拔 SLA 写训练作业的恢复时间。</p><p><span class="marginnote">浸没式冷却是另一条产品线，故障与维护模型又不同。没有部署就不要把浸没的营销 PUE 写进当前风冷/冷板机房的规划。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用液冷当节能的唯一理由——主因是密度。不要忽略凝露：进水过冷、机房露点高，冷板会结露。不要把未公开的「某代 120 kW 机柜」数字写进课；用你合同里的规格。下一课 GPU 故障模式包含热相关的 Xid 与静默错误，冷却是诱因之一。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>液冷支撑功率密度，把故障域收成 CDU / 机柜级。</li><li>单卡降频通过集体同步变成整步变慢。</li><li>监控水侧与 GPU 时钟对齐；控制环必须扛住训练方波。</li><li>维护与 SLA 不能按风冷热插拔来写。</li><li>出处：公开超节点液冷形态；设施进水温度与泄漏保护实践。</li></ul>',9))])}const P=r(h,[["render",A]]);export{B as __pageData,P as default};
